"use client";

import * as React from "react";
import { cn } from "../../lib/utils.js";

/**
 * Gantt chart — tasks as horizontal bars across a time axis, with
 * optional dependency arrows and progress fills. Pure SVG; no heavy
 * peer dependency.
 *
 * Distinct from TimeAxis (point events) and Sequence (actor messages):
 * Gantt encodes DURATION (start → end) per task and supports task-to-
 * task dependency arrows.
 *
 * @example
 * <Gantt
 *   tasks={[
 *     { id: "design", label: "Design", start: "2025-01-01", end: "2025-01-15", progress: 1 },
 *     { id: "build", label: "Build", start: "2025-01-10", end: "2025-02-20", progress: 0.6, dependencies: ["design"] },
 *     { id: "ship", label: "Ship", start: "2025-02-15", end: "2025-02-28", dependencies: ["build"] },
 *   ]}
 * />
 */
export type GanttTask = {
	id: string;
	label: string;
	start: Date | string | number;
	end: Date | string | number;
	/** Optional progress 0..1; renders as a filled portion of the bar. */
	progress?: number;
	/** Optional list of task ids this task depends on; arrow drawn from each. */
	dependencies?: string[];
};

export interface GanttProps extends Omit<React.SVGAttributes<SVGSVGElement>, "children"> {
	/** Tasks in display order (rows top-to-bottom). */
	tasks: GanttTask[];
	/** Pixel width of the rendered SVG. Default 800. */
	width?: number;
	/** Pixel height of each task row. Default 32. */
	rowHeight?: number;
	/** Pixel reserved on the left for task labels. Default 140. */
	labelMargin?: number;
	/** Number of axis ticks to show. Default 6. */
	tickCount?: number;
	/** Fired when a task bar is clicked. */
	onTaskClick?: (task: GanttTask) => void;
}

interface LaidOutTask {
	task: GanttTask;
	rowIndex: number;
	x: number;
	y: number;
	w: number;
	h: number;
	progressW: number;
}

interface DepArrow {
	from: { x: number; y: number };
	to: { x: number; y: number };
	id: string;
}

interface AxisTick {
	x: number;
	label: string;
}

const HEADER_HEIGHT = 40;
const ROW_PADDING = 6;

function Gantt({
	tasks,
	width = 800,
	rowHeight = 32,
	labelMargin = 140,
	tickCount = 6,
	onTaskClick,
	className,
	...rest
}: GanttProps) {
	const laidOut = React.useMemo(
		() => layout(tasks, width, rowHeight, labelMargin, tickCount),
		[tasks, width, rowHeight, labelMargin, tickCount],
	);

	const totalHeight = HEADER_HEIGHT + tasks.length * rowHeight + ROW_PADDING;
	const desc = `Gantt with ${tasks.length} task${tasks.length === 1 ? "" : "s"}, range ${laidOut.startLabel} to ${laidOut.endLabel}`;
	// Per-instance arrowhead marker id keeps two <Gantt> on a page
	// from sharing a <defs> id.
	const arrowId = React.useId().replace(/:/g, "-");

	return (
		<svg
			{...rest}
			data-hex-gantt
			role="img"
			width={width}
			height={totalHeight}
			viewBox={`0 0 ${width} ${totalHeight}`}
			className={cn("block", className)}
		>
			<title>Gantt chart</title>
			<desc>{desc}</desc>
			<defs>
				<marker
					id={`hex-gantt-arrow-${arrowId}`}
					viewBox="0 0 10 10"
					refX="10"
					refY="5"
					markerWidth="5"
					markerHeight="5"
					orient="auto-start-reverse"
				>
					<path d="M 0 0 L 10 5 L 0 10 z" fill="hsl(var(--muted-foreground))" />
				</marker>
			</defs>
			{/* Axis header */}
			<g data-hex-gantt-axis>
				<line
					x1={labelMargin}
					x2={width - 16}
					y1={HEADER_HEIGHT - 8}
					y2={HEADER_HEIGHT - 8}
					stroke="hsl(var(--muted-foreground))"
					strokeWidth={1}
				/>
				{laidOut.ticks.map((t, i) => (
					<g key={`tick-${i}`} data-hex-gantt-tick>
						<line
							x1={t.x}
							x2={t.x}
							y1={HEADER_HEIGHT - 8}
							y2={totalHeight - 4}
							stroke="hsl(var(--muted-foreground))"
							strokeOpacity={0.15}
							strokeWidth={1}
						/>
						<text
							x={t.x}
							y={HEADER_HEIGHT - 14}
							textAnchor="middle"
							fontSize={10}
							fill="hsl(var(--muted-foreground))"
						>
							{t.label}
						</text>
					</g>
				))}
			</g>
			{/* Row labels */}
			<g data-hex-gantt-labels>
				{laidOut.tasks.map((t) => (
					<text
						key={`label-${t.task.id}`}
						x={labelMargin - 8}
						y={t.y + t.h / 2}
						dy="0.35em"
						textAnchor="end"
						fontSize={11}
						fill="hsl(var(--foreground))"
					>
						{t.task.label}
					</text>
				))}
			</g>
			{/* Dependency arrows: elbow-and-jog routing — when the target
			    task starts before (or near) the source's right edge, route
			    out past the source first to avoid drawing through its bar. */}
			<g data-hex-gantt-deps fill="none">
				{laidOut.deps.map((d) => {
					const ELBOW = 8;
					const needsJog = d.to.x < d.from.x + ELBOW;
					const path = needsJog
						? `M${d.from.x},${d.from.y} L${d.from.x + ELBOW},${d.from.y} L${d.from.x + ELBOW},${d.to.y} L${d.to.x},${d.to.y}`
						: `M${d.from.x},${d.from.y} L${(d.from.x + d.to.x) / 2},${d.from.y} L${(d.from.x + d.to.x) / 2},${d.to.y} L${d.to.x},${d.to.y}`;
					return (
						<path
							key={d.id}
							data-hex-gantt-dep
							d={path}
							stroke="hsl(var(--muted-foreground))"
							strokeOpacity={0.55}
							strokeWidth={1}
							markerEnd={`url(#hex-gantt-arrow-${arrowId})`}
						/>
					);
				})}
			</g>
			{/* Task bars */}
			<g data-hex-gantt-tasks>
				{laidOut.tasks.map((t) => {
					const interactive = Boolean(onTaskClick);
					const handleActivate = () => onTaskClick?.(t.task);
					return (
						<g
							key={t.task.id}
							data-hex-gantt-task
							data-row={t.rowIndex}
							className={interactive ? "focus-visible:outline-none focus-visible:outline-2 focus-visible:outline-ring" : undefined}
							role={interactive ? "button" : undefined}
							tabIndex={interactive ? 0 : undefined}
							aria-label={
								interactive
									? `${t.task.label}, ${formatDate(toDate(t.task.start))} to ${formatDate(toDate(t.task.end))}${t.task.progress != null ? `, ${Math.round((t.task.progress ?? 0) * 100)}% complete` : ""}`
									: undefined
							}
							style={interactive ? { cursor: "pointer" } : undefined}
							onClick={interactive ? handleActivate : undefined}
							onKeyDown={interactive ? (e) => activateOnKey(e, handleActivate) : undefined}
						>
							<rect
								x={t.x}
								y={t.y}
								width={Math.max(2, t.w)}
								height={t.h}
								rx={4}
								ry={4}
								fill="hsl(var(--primary))"
								fillOpacity={0.25}
								stroke="hsl(var(--primary))"
								strokeWidth={1}
							/>
							{t.progressW > 0 ? (
								<>
									<rect
										x={t.x}
										y={t.y}
										width={t.progressW}
										height={t.h}
										rx={4}
										ry={4}
										fill="hsl(var(--primary))"
										fillOpacity={0.7}
									/>
									{/* Hard right-edge line keeps the progress boundary visible for
									    color-blind viewers and on low-contrast themes. Skipped at
									    100% progress where it overlaps the bar's own border. */}
									{t.progressW < t.w - 0.5 ? (
										<line
											x1={t.x + t.progressW}
											x2={t.x + t.progressW}
											y1={t.y}
											y2={t.y + t.h}
											stroke="hsl(var(--primary))"
											strokeWidth={1}
										/>
									) : null}
								</>
							) : null}
						</g>
					);
				})}
			</g>
		</svg>
	);
}

function layout(
	tasks: GanttTask[],
	width: number,
	rowHeight: number,
	labelMargin: number,
	tickCount: number,
): {
	tasks: LaidOutTask[];
	deps: DepArrow[];
	ticks: AxisTick[];
	startLabel: string;
	endLabel: string;
} {
	if (tasks.length === 0) {
		return { tasks: [], deps: [], ticks: [], startLabel: "—", endLabel: "—" };
	}

	const axisLeft = labelMargin;
	const axisRight = width - 16;
	const usable = axisRight - axisLeft;

	// Drop NaN-bearing endpoints so the axis range stays finite. Tasks with
	// either bound un-parseable get rendered with their own zero-width
	// fallback below; we still want them in the row layout, just clipped to
	// the axis edges.
	const allTimes = tasks
		.flatMap((t) => [toDate(t.start).getTime(), toDate(t.end).getTime()])
		.filter((t) => Number.isFinite(t));
	if (allTimes.length === 0) {
		return { tasks: [], deps: [], ticks: [], startLabel: "—", endLabel: "—" };
	}
	const minTs = Math.min(...allTimes);
	const maxTs = Math.max(...allTimes);
	const span = Math.max(1, maxTs - minTs);

	const tToX = (t: number) => axisLeft + ((t - minTs) / span) * usable;

	const laidOutTasks: LaidOutTask[] = tasks.map((task, i) => {
		const startTs = toDate(task.start).getTime();
		const endTs = toDate(task.end).getTime();
		const x = tToX(startTs);
		const w = Math.max(0, tToX(endTs) - x);
		const y = HEADER_HEIGHT + i * rowHeight + ROW_PADDING / 2;
		const h = rowHeight - ROW_PADDING;
		const progress = clamp01(task.progress ?? 0);
		return {
			task,
			rowIndex: i,
			x,
			y,
			w,
			h,
			progressW: w * progress,
		};
	});

	const byId = new Map(laidOutTasks.map((t) => [t.task.id, t]));
	const deps: DepArrow[] = [];
	laidOutTasks.forEach((t) => {
		(t.task.dependencies ?? []).forEach((depId, k) => {
			const from = byId.get(depId);
			if (!from) return;
			deps.push({
				from: { x: from.x + from.w, y: from.y + from.h / 2 },
				to: { x: t.x, y: t.y + t.h / 2 },
				id: `${depId}-${t.task.id}-${k}`,
			});
		});
	});

	// Generate ticks, then dedupe consecutive identical labels — at year-scale
	// or month-scale spans the formatter often emits the same string twice
	// (e.g. two ticks both inside January render as "2025-01"). Blanking the
	// duplicate keeps the gridline but drops the noisy repeated text.
	const rawTicks: AxisTick[] = [];
	for (let i = 0; i < tickCount; i++) {
		const ts = minTs + (i / Math.max(1, tickCount - 1)) * span;
		rawTicks.push({ x: tToX(ts), label: formatTick(new Date(ts), span) });
	}
	const ticks: AxisTick[] = rawTicks.map((t, i) => ({
		x: t.x,
		label: i > 0 && rawTicks[i - 1]?.label === t.label ? "" : t.label,
	}));

	return {
		tasks: laidOutTasks,
		deps,
		ticks,
		startLabel: formatDate(new Date(minTs)),
		endLabel: formatDate(new Date(maxTs)),
	};
}

function toDate(v: Date | string | number): Date {
	if (v instanceof Date) return v;
	if (typeof v === "number") return new Date(v);
	return new Date(v);
}

function clamp01(v: number): number {
	return v < 0 ? 0 : v > 1 ? 1 : v;
}

function formatDate(d: Date): string {
	if (Number.isNaN(d.getTime())) return "—";
	return d.toISOString().slice(0, 10);
}

function formatTick(d: Date, spanMs: number): string {
	if (Number.isNaN(d.getTime())) return "—";
	const ONE_DAY = 24 * 60 * 60 * 1000;
	// Switch to MM-DD up to ~3 months — at 30 days the original threshold
	// produced "2025-01" / "2025-01" duplicates for ticks landing in the
	// same month. MM-DD scales to ~90 days before adjacent ticks merge.
	if (spanMs <= 90 * ONE_DAY) return d.toISOString().slice(5, 10); // MM-DD
	if (spanMs <= 730 * ONE_DAY) return d.toISOString().slice(0, 7); // YYYY-MM
	return String(d.getUTCFullYear());
}

function activateOnKey(e: React.KeyboardEvent, fn: () => void): void {
	if (e.key === "Enter" || e.key === " ") {
		e.preventDefault();
		fn();
	}
}

export { Gantt };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex Core: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const SAFE_URL_SCHEMES = ["http:", "https:", "mailto:"] as const;

/**
 * Allowlist a URL for use as an `<a href>` against untrusted input.
 *
 * Returns the raw string when it's `http(s):` / `mailto:` / a relative
 * URL (no scheme); returns `undefined` otherwise. Defends against
 * `javascript:` / `data:` / `vbscript:` injection from streamed model
 * output or third-party JSON payloads that flow into citation chips.
 *
 * Inside a Markdown render path, `rehype-sanitize` already strips
 * `javascript:` from inline-link hrefs — but it does NOT introspect
 * JSON nested inside attribute values (e.g. `<sources data='[…]'/>`),
 * so the components that consume that data must guard themselves.
 *
 * @param raw - The candidate URL, or `undefined` when none was supplied.
 * @returns The URL when safe to render, otherwise `undefined`.
 */
export function safeUrl(raw: string | undefined): string | undefined {
	if (raw === undefined || raw === "") return undefined;
	// Relative URLs have no scheme — `new URL(relative)` throws without a base,
	// so a thrown URL means either malformed input OR a relative path. Treat
	// "throws + does not contain a colon" as a relative path (safe).
	let parsed: URL;
	try {
		parsed = new URL(raw);
	} catch {
		return raw.includes(":") ? undefined : raw;
	}
	return SAFE_URL_SCHEMES.some((scheme) => scheme === parsed.protocol) ? raw : undefined;
}
